css:
@import url("https://fonts.googleapis.com/css2?family=Asap+Condensed:wght@600;700&family=Asap:wght@400;500;600&display=swap");
:root{--in:#23305E;--in2:#34457F;--or:#F08A24;--or2:#C96A0E;--pb:#EEF1F7;--ink:#1B2238;--gr:#555F76;--ln:#D9DFEB;--h:"Asap Condensed",Impact,sans-serif;--b:"Asap",system-ui,sans-serif}
*,*::before,*::after{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;font-family:var(--b);font-size:17px;line-height:1.65;color:var(--ink);background:#fff}
img{max-width:100%;height:auto;display:block}a{color:inherit}h1,h2,h3{font-family:var(--h);font-weight:700;margin:0;line-height:1.02}
.wrap{max-width:1180px;margin:0 auto;padding:0 22px}.skip{position:absolute;left:-999px}.skip:focus{left:10px;top:10px;background:var(--or);padding:8px;z-index:99}
:focus-visible{outline:3px solid var(--or);outline-offset:2px}
.hd{background:var(--in);color:#fff}.nav{display:flex;justify-content:space-between;align-items:center;height:78px;position:relative}.logo{font-family:var(--h);font-size:28px;text-decoration:none;display:flex;gap:10px;align-items:center}
.menu{display:flex;gap:26px;list-style:none;margin:0;padding:0;font-weight:500}.menu a{text-decoration:none}.menu a:hover{color:var(--or)}
.burger{display:none;background:none;border:2px solid #fff;color:#fff;width:44px;height:40px;border-radius:8px;font-size:20px;cursor:pointer}
.hero{background:var(--in);color:#fff;padding:30px 0 0;overflow:hidden}.hero .wrap{display:grid;grid-template-columns:1fr 1fr;gap:40px;align-items:end}
.hero .t{padding-bottom:70px}.hero h1{font-size:clamp(50px,7vw,96px);text-transform:uppercase}.hero h1 span{color:var(--or)}
.hero p{font-size:19px;color:#C9D1EA;max-width:30em;margin:22px 0 28px}
.btn{display:inline-block;background:var(--or);color:var(--ink);text-decoration:none;font:600 17px var(--b);padding:14px 26px;border-radius:6px;border:0;cursor:pointer}.btn.w{background:transparent;color:#fff;box-shadow:inset 0 0 0 2px #fff}.btn.d{background:var(--in);color:#fff}
.row{display:flex;flex-wrap:wrap;gap:12px}
.hero img{width:100%;aspect-ratio:4/3.3;object-fit:cover;border-radius:10px 10px 0 0}
.facts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));border-top:1px solid var(--in2);margin-top:30px;padding-top:20px;gap:10px}.facts b{display:block;font-family:var(--h);font-size:34px;color:#fff}.facts span{font-size:14px;color:#C9D1EA}
section{padding:86px 0}.sh{max-width:660px;margin-bottom:34px}.sh h2{font-size:clamp(38px,5vw,62px);text-transform:uppercase;color:var(--in)}.sh p{color:var(--gr);margin:12px 0 0;font-size:18px}
.bm{background:var(--pb)}.bg{display:grid;grid-template-columns:.8fr 1.2fr;gap:50px;align-items:start}.bg>div{min-width:0}
.fig{position:relative;max-width:340px;margin:0 auto}.fig svg{width:100%;height:auto;display:block}
.hs{position:absolute;width:30px;height:30px;border-radius:50%;border:3px solid #fff;background:var(--or);transform:translate(-50%,-50%);cursor:pointer;box-shadow:0 0 0 0 rgba(240,138,36,.5);padding:0}
.hs[aria-pressed=true]{background:var(--in);box-shadow:0 0 0 8px rgba(35,48,94,.2)}
.hs:hover{transform:translate(-50%,-50%) scale(1.15)}
.chips{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:22px}.chips button{font:600 15px var(--b);background:#fff;border:2px solid var(--ln);border-radius:6px;padding:8px 14px;cursor:pointer;color:var(--ink)}.chips button[aria-pressed=true]{background:var(--in);border-color:var(--in);color:#fff}
.area{background:#fff;border-radius:12px;padding:28px;border-left:6px solid var(--or)}.area h3{font-size:40px;text-transform:uppercase;color:var(--in)}.area .sub{color:var(--gr);margin:4px 0 18px}
.cond{display:flex;flex-wrap:wrap;gap:8px;margin:0 0 20px;padding:0;list-style:none}.cond li{background:var(--pb);border-radius:30px;padding:6px 14px;font-size:15px;font-weight:500}
.meta{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-bottom:22px}.meta div{background:var(--pb);border-radius:8px;padding:12px 14px;font-size:14px;color:var(--gr)}.meta b{display:block;font-family:var(--h);font-size:24px;color:var(--ink)}
.how .steps{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:0;counter-reset:s}
.how .st{padding:0 26px 0 0;counter-increment:s}.how .st:before{content:counter(s);display:grid;place-items:center;width:52px;height:52px;border-radius:50%;background:var(--or);font-family:var(--h);font-size:26px;margin-bottom:14px}
.how .st h3{font-size:26px;text-transform:uppercase}.how .st p{color:var(--gr);margin:6px 0 0}
.pr{background:var(--in);color:#fff}.pr .sh h2{color:#fff}.pr .sh p{color:#C9D1EA}
.ptab{width:100%;border-collapse:collapse}.ptab th,.ptab td{text-align:left;padding:16px 10px;border-bottom:1px solid var(--in2)}.ptab th{font-weight:500;color:#C9D1EA;font-size:15px}.ptab td:last-child,.ptab th:last-child{text-align:right}
.ptab td b{font-family:var(--h);font-size:22px;letter-spacing:.01em}.ptab .p{font-family:var(--h);font-size:28px;color:var(--or)}
.tw{overflow-x:auto}
.bk .wrap{display:grid;grid-template-columns:1fr 1fr;gap:50px}
form{background:var(--pb);border-radius:12px;padding:30px}.fr{display:grid;grid-template-columns:1fr 1fr;gap:14px}.fr>div{min-width:0}
label{display:block;font-weight:600;font-size:15px;margin-bottom:6px}input,select,textarea{width:100%;font:16px var(--b);padding:12px;border:2px solid var(--ln);border-radius:6px;margin-bottom:14px;color:var(--ink);background:#fff}
.msg{visibility:hidden;margin:12px 0 0;font-weight:600;color:var(--in)}.msg.on{visibility:visible}
.faq details{border-bottom:1px solid var(--ln);padding:16px 0}.faq summary{font-weight:600;font-size:19px;cursor:pointer}.faq p{margin:10px 0 0;color:var(--gr)}
footer{background:var(--in);color:#C9D1EA;padding:32px 0;font-size:15px}footer .wrap{display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px}
@media (max-width:980px){.hero .wrap,.bg,.bk .wrap{grid-template-columns:1fr}.how .steps{grid-template-columns:1fr 1fr;gap:28px}}
@media (max-width:760px){.burger{display:block}.menu{display:none;position:absolute;top:78px;left:0;right:0;background:var(--in);flex-direction:column;padding:18px 22px;z-index:30}.menu.open{display:flex}.fr,.meta{grid-template-columns:1fr}.how .steps{grid-template-columns:1fr}.fig{max-width:260px}}
@media (prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}.hs:hover{transform:translate(-50%,-50%)}}

javascript:
(()=>{const $=id=>document.getElementById(id);
const A=[["neck","Neck",50,15,"Stiffness, headaches and pain from desk work.",["Stiff neck","Tension headaches","Whiplash","Pinched nerve"],"3 to 5","2 to 6 weeks","10 min a day"],
["shoulder","Shoulder",30,22,"From swimmers and tradies to frozen shoulders.",["Rotator cuff strain","Frozen shoulder","Dislocation rehab","Bursitis"],"4 to 8","4 to 12 weeks","15 min a day"],
["back","Lower back",50,45,"The most common reason people see us.",["Disc bulge","Sciatica","Muscle spasm","Pregnancy back pain"],"4 to 6","3 to 8 weeks","10 min a day"],
["wrist","Elbow and wrist",20,44,"Pain from typing, lifting babies or racquet sports.",["Tennis elbow","Carpal tunnel","Wrist sprain","RSI"],"3 to 6","3 to 8 weeks","5 min, twice a day"],
["hip","Hip",38,55,"Aches when walking, sleeping on your side or climbing stairs.",["Hip bursitis","Arthritis","Hip replacement rehab","Groin strain"],"4 to 8","4 to 12 weeks","15 min a day"],
["knee","Knee",38,76,"Runners, footballers and anyone after knee surgery.",["ACL rehab","Runner's knee","Meniscus tear","Knee arthritis"],"6 to 12","6 to 16 weeks","20 min a day"],
["ankle","Ankle and foot",40,94,"Rolled ankles and heel pain in the morning.",["Ankle sprain","Plantar fasciitis","Achilles pain","Shin splints"],"3 to 6","2 to 8 weeks","10 min a day"]];
let cur='back';const fig=$('fig');
A.forEach(a=>{const b=document.createElement('button');b.type='button';b.className='hs';b.style.left=a[2]+'%';b.style.top=a[3]+'%';b.dataset.k=a[0];b.setAttribute('aria-label',a[1]);fig.appendChild(b)});
$('chips').innerHTML=A.map(a=>`<button type="button" data-k="${a[0]}">${a[1]}</button>`).join('');$('ba').innerHTML=A.map(a=>`<option>${a[1]}</option>`).join('')+'<option>Somewhere else</option>';
function show(){const a=A.find(x=>x[0]===cur);document.querySelectorAll('[data-k]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.k===cur));
$('an').textContent=a[1];$('as').textContent=a[4];$('ac').innerHTML=a[5].map(c=>`<li>${c}</li>`).join('');$('aw').textContent=a[6];$('ah').textContent=a[7];$('ae').textContent=a[8];$('ba').value=a[1]}
document.addEventListener('click',e=>{const b=e.target.closest('[data-k]');if(!b)return;cur=b.dataset.k;show()});show();
const nd=new Date(Date.now()+864e5);$('bd').value=nd.toISOString().slice(0,10);$('bd').min=new Date().toISOString().slice(0,10);
$('bf').onsubmit=e=>{e.preventDefault();$('msg').textContent=`Thanks ${$('bn').value}. We'll call ${$('bph').value} within 2 working hours to book your ${$('ba').value.toLowerCase()} assessment.`;$('msg').classList.add('on')};
})();
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
